<?php
use GoldCommerce\{Plugin,Quotes,Database,Rates};
wp_set_current_user(1);$results=[];
$check=static function($name,$fn)use(&$results){try{$fn();$results[]=['test'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['test'=>$name,'status'=>'FAIL','error'=>$e->getMessage()];}};
$assert=static function($v){if(!$v)throw new RuntimeException('Assertion failed');};
$product=static function(){ $p=new WC_Product_Simple();$p->set_name('Extended fixture');$p->set_status('publish');$p->set_catalog_visibility('hidden');$p->set_regular_price('100');$p->set_virtual(true);$p->set_manage_stock(true);$p->set_stock_quantity(10);$p->set_tax_status('none');$p->update_meta_data('_gc_product',['price_type'=>'MANUAL_FINAL','fixed_price'=>'100','net_weight'=>'0','gross_weight'=>'0']);$p->save();return $p;};
$new=static function()use($product){$o=wc_create_order(['status'=>'gc-await-quote']);$o->set_currency('IRR');$o->set_billing_email('extended@example.test');$o->add_product($product(),1);$o->update_meta_data('_gc_specialized','yes');$o->save();$q=Quotes::issue($o->get_id());$b=Quotes::begin($q['uuid'],$q['token']);return [$o,$q,$b];};
$check('PAY.deadline_snapshotted',static function()use($new,$assert){[$o,$q,$b]=$new();$start=Quotes::get($q['uuid']);$settings=Plugin::settings();$changed=$settings;$changed['payment_grace']=86400;update_option('gc_settings',$changed);$assert(Quotes::deadline(Quotes::get($q['uuid']))===(int)$start['settlement_deadline']);update_option('gc_settings',$settings);});
$check('PAY.receipt_recovery_after_crash',static function()use($new,$assert){[$o,$q,$b]=$new();global $wpdb;$tx='CRASH-'.wp_generate_uuid4();$wpdb->insert(Database::table('payment_receipts'),['provider'=>'adapter','transaction_id'=>$tx,'order_id'=>$o->get_id(),'amount_irr'=>'100','intent'=>$b['intent'],'status'=>'received','received_at'=>time()]);$assert(Quotes::settle($o->get_id(),$tx,'100',$b['intent'])==='paid');$assert(wc_get_order($o->get_id())->is_paid());});
$check('PAY.late_beyond_grace_kept_review',static function()use($new,$assert){[$o,$q,$b]=$new();global $wpdb;$wpdb->update(Database::table('quotes'),['settlement_deadline'=>time()-1],['uuid'=>$q['uuid']]);$assert(Quotes::settle($o->get_id(),'LATE-'.wp_generate_uuid4(),'100',$b['intent'])==='payment_review');$assert(!wc_get_order($o->get_id())->is_paid());});
$check('PAY.generic_gateway_late_receipt_retained',static function()use($new,$assert){[$o,$q,$b]=$new();global $wpdb;$wpdb->update(Database::table('quotes'),['settlement_deadline'=>time()-1],['uuid'=>$q['uuid']]);$o=wc_get_order($o->get_id());$o->payment_complete('GENERIC-'.wp_generate_uuid4());$o=wc_get_order($o->get_id());$assert(!$o->is_paid());$assert($o->get_transaction_id()!=='');$assert((int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Database::table('payment_receipts')." WHERE order_id=%d AND status='payment_review'",$o->get_id()))===1);});
$check('PAY.item_mutation_same_total_rejected',static function()use($new,$assert){[$o,$q,$b]=$new();$item=current($o->get_items());$item->set_quantity(2);$item->save();$assert(Quotes::settle($o->get_id(),'MUTATION-'.wp_generate_uuid4(),'100',$b['intent'])==='payment_review');});
$check('PRICE.expired_latest_never_revives_old',static function()use($assert){$name='testsource-'.wp_generate_uuid4();Rates::put(['value'=>'10','currency'=>'IRR','unit'=>'IRR_PER_GRAM','valid_until'=>time()+500],$name);$q=Rates::put(['value'=>'11','currency'=>'IRR','unit'=>'IRR_PER_GRAM','valid_until'=>time()+100],$name);global $wpdb;$tick=$q;$tick['valid_until']=time()-1;$wpdb->update(Database::table('rate_ticks'),['payload'=>wp_json_encode($tick)],['version'=>$q['version']]);$thrown=false;try{Rates::latest($name);}catch(Throwable $e){$thrown=true;}$assert($thrown);});
$check('PRICE.inheritance',static function()use($product,$assert){$p=$product();$m=Plugin::model($p);$m['price_type']='INHERIT';$m['category']='coin';$p->update_meta_data('_gc_product',$m);$p->save();$settings=Plugin::settings();$s=$settings;$s['category_strategies']['coin']='MANUAL_FINAL';update_option('gc_settings',$s);$assert(Plugin::price($p)['amount_irr']==='100');update_option('gc_settings',$settings);});
$check('AGAH.float_and_invalid_wire_money_rejected',static function()use($assert){foreach([123.5,'NaN','1e6','-1'] as $amount){$thrown=false;try{GoldAgah\MockProvider::authority('AGAH_AUTHORITATIVE_FINAL_PRICE',['currency'=>'IRR','scale'=>2,'amount_minor'=>$amount],[]);}catch(Throwable $e){$thrown=true;}$assert($thrown);}});
$out=['suite'=>'extended','php'=>PHP_VERSION,'at_utc'=>gmdate('c'),'results'=>$results];file_put_contents('/project/evidence/extended-php'.PHP_MAJOR_VERSION.PHP_MINOR_VERSION.'.json',wp_json_encode($out,JSON_PRETTY_PRINT));echo wp_json_encode($out,JSON_PRETTY_PRINT);if(array_filter($results,static fn($r)=>$r['status']==='FAIL'))WP_CLI::halt(1);
